(()=>{
const q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)],isFI=()=>q('#applicant').value==='institution';
q('#applicant').append(new Option('A financial institution','institution'));
const choice=document.createElement('section');choice.className='panel applicant-cards';choice.innerHTML='<div class="three"><div><h2>I am an individual</h2><button type="button" data-route="individual">Private banking</button></div><div><h2>I am a legal entity</h2><div class="route-options"><button type="button" data-route="bank">Bank account</button><button type="button" data-route="merchant">Merchant account</button><button type="button" data-route="both">Bank & merchant accounts</button><button type="button" data-route="financing">Financing</button></div></div><div><h2>I am a financial institution</h2><button type="button" data-route="institution">Correspondent / payment accounts</button><p class="hint">For banks, EMIs, payment institutions, MSBs and virtual-asset providers.</p></div></div>';
const page1=q('[data-screen="1"]');page1.querySelector('.panel').before(choice);
const style=document.createElement('style');style.textContent='.applicant-cards .three>div{border:1px solid #e5ded5;border-radius:8px;padding:16px}.applicant-cards h2{font-size:18px}.route-options{display:grid;gap:8px}.applicant-cards button{width:100%;text-align:left}.applicant-cards button[aria-pressed=true]{background:#826a50;color:white}';document.head.append(style);
const legacy=q('#applicant').closest('.panel');
function cards(){legacy.hidden=true;labels[1]='Applicant';if(isFI())q('#agent-section').hidden=true;page1.querySelector('h1').textContent='Choose your applicant type and service';const selected=q('#applicant').value==='individual'?'individual':isFI()?'institution':q('#account-type').value;all('[data-route]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.route===selected?'true':'false'));q('#company-name').closest('.panel').hidden=q('#applicant').value==='individual';}
all('[data-route]').forEach(b=>b.onclick=()=>{const v=b.dataset.route;q('#applicant').value=v==='individual'?'individual':v==='institution'?'institution':'company';q('#applicant').dispatchEvent(new Event('change',{bubbles:true}));if(!['individual','institution'].includes(v)){q('#account-type').value=v;q('#account-type').dispatchEvent(new Event('change',{bubbles:true}));}cards();});
const oldApplicant=q('#applicant').onchange;q('#applicant').onchange=()=>{oldApplicant();cards();};
const input=(id,title,type='text',required=true)=>`<label class="field"><span>${title}${required?'':' <small>(optional)</small>'}</span><input id="${id}" type="${type}" ${required?'required':''} ${type==='number'?'min="0"':''}></label>`;
const sel=(id,title,opts)=>`<label class="field"><span>${title}</span><select id="${id}" required><option value="">Select…</option>${opts.map(x=>'<option>'+x+'</option>').join('')}</select></label>`;
const area=(id,title)=>`<label class="field"><span>${title}</span><textarea id="${id}" required ></textarea></label>`;
const checks=(id,title,opts)=>`<fieldset id="${id}"><legend>${title}</legend><div class="checks">${opts.map(x=>'<label><input type="checkbox" value="'+x+'">'+x+'</label>').join('')}</div></fieldset>`;
const countries=(id,title)=>`<div class="field"><span>${title}</span><input type="hidden" id="${id}"><div class="country-picker" id="${id}-picker"></div></div>`;
function page(n,title,lead,body){const s=document.createElement('div');s.className='screen';s.dataset.screen=n;s.hidden=true;s.innerHTML='<div class="account-section">FINANCIAL INSTITUTION</div><h1>'+title+'</h1><p class="lead">'+lead+'</p><section class="panel">'+body+'</section>';q('main').append(s);}
page(30,'Institution & regulatory status','Describe the institution that will hold the account.',checks('fi-type','Institution type — select all that apply',['Bank','Electronic money institution (EMI)','Payment institution / PSP','Money services business (MSB)','Virtual-asset service provider (VASP)','Other'])+area('fi-activities','Briefly describe your financial services and operating model')+sel('fi-status','Regulatory status',['Licensed / authorised','Registered','SRO member','More than one of these','Application pending','Other'])+area('fi-regulatory','Regulator or SRO, jurisdiction, reference number and permitted activities')+input('fi-register-link','Official register link','url',false)+input('fi-website','Institution website','url',false));
page(31,'Underlying clients','Describe the customers whose activity would pass through this relationship.',checks('fi-clients','Client types',['Individuals','Businesses','Other financial institutions'])+area('fi-client-profile','Main client industries and business activities')+countries('fi-client-countries','Countries where underlying clients are based')+sel('fi-downstream','Will you process payments for other financial institutions and their clients?',['Yes','No','Not yet determined'])+'<div id="fi-downstream-detail" hidden>'+area('fi-downstream-text','Describe those institutions, their countries and the customers they serve')+'</div>'+sel('fi-access','Will underlying clients have direct access to operate the account?',['Yes','No','Not yet determined'])+'<div id="fi-access-detail" hidden>'+area('fi-access-text','Explain how clients would access or use the account')+'</div>');
page(32,'Services & expected flows','Tell us what the proposed relationship must support.',checks('fi-services','Services required',['Own operating account','Client-funds safeguarding / segregation','Collection and payout services','Cross-border payments','FX conversion','Clearing / settlement','Other'])+area('fi-fund-model','Whose money will be held or transferred, and how will it move?')+checks('fi-currencies','Currencies',['EUR','GBP','USD','CHF','Other'])+'<div id="fi-other-currency" hidden>'+input('fi-other-currency-text','Other currencies')+'</div>'+countries('fi-incoming','Incoming transaction countries')+countries('fi-outgoing','Outgoing transaction countries')+sel('fi-reporting','Reporting currency for amounts below',['EUR','GBP','USD','CHF'])+'<div class="grid">'+input('fi-in-value','Expected incoming amount per month','number')+input('fi-out-value','Expected outgoing amount per month','number')+input('fi-in-count','Expected incoming transactions per month','number')+input('fi-out-count','Expected outgoing transactions per month','number')+'</div>');
page(33,'Compliance & existing relationships','A short overview now; detailed due diligence follows with the provider.',sel('fi-aml','Do you have documented AML/KYC, sanctions-screening and transaction-monitoring controls?',['Yes','Partly / in development','No'])+sel('fi-ddq','Is a completed due-diligence questionnaire available (e.g. Wolfsberg CBDDQ/FCCQ, where applicable)?',['Yes','No','Not applicable'])+sel('fi-audit','Is a recent independent AML review or audit available?',['Yes','No'])+input('fi-compliance-name','Compliance contact name')+input('fi-compliance-email','Compliance contact email','email')+input('fi-existing','Existing correspondent or payment-account providers','text',false)+area('fi-reason','Why are you seeking this relationship?'));
q('#fi-client-profile').placeholder='Describe underlying client sectors, including any adult industry, gambling/betting, forex or crypto exposure.';
['fi-client-countries','fi-incoming','fi-outgoing'].forEach(id=>initCountryPicker(q('#'+id+'-picker'),id,q('#'+id)));
[['fi-downstream','fi-downstream-detail'],['fi-access','fi-access-detail']].forEach(([id,target])=>q('#'+id).onchange=()=>q('#'+target).hidden=q('#'+id).value!=='Yes');q('#fi-currencies').onchange=()=>q('#fi-other-currency').hidden=!q('#fi-currencies input[value="Other"]').checked;
['fi-in-count','fi-out-count'].forEach(id=>q('#'+id).step='1');
Object.assign(labels,{30:'Institution & regulation',31:'Underlying clients',32:'Services & flows',33:'Compliance'});
const previousFlow=activeFlow;activeFlow=function(){return isFI()?[0,1,30,31,32,33,4,5]:previousFlow();};
const previousRefresh=refreshFlow;refreshFlow=function(){previousRefresh();cards();};window.refreshFlow=refreshFlow;
const previousShow=showPage;showPage=function(n){if(isFI()&&activeFlow().indexOf(n)>activeFlow().indexOf(currentPage)){const groups={30:['fi-type'],31:['fi-clients'],32:['fi-services','fi-currencies']};for(const id of groups[currentPage]||[]){if(!q('#'+id+' input:checked')){note('Please choose at least one option for '+q('#'+id+' legend').textContent+'.');return;}}for(const id of currentPage===31?['fi-client-countries']:currentPage===32?['fi-incoming','fi-outgoing']:[]){if(q('#'+id+'-picker').offsetParent!==null&&!q('#'+id).value){note('Please select the relevant client or transaction countries.');return;}}}previousShow(n);};
const previousReview=review;review=function(){previousReview();if(isFI()){const terms=[...q('#review-summary').querySelectorAll('dt')];const service=terms.find(t=>t.textContent==='Requested services');if(service)service.nextElementSibling.textContent='Correspondent / payment accounts';const act=terms.find(t=>t.textContent==='Business activity');if(act)act.nextElementSibling.textContent=q('#fi-activities').value;const curr=terms.find(t=>t.textContent==='Account currencies');if(curr)curr.nextElementSibling.textContent=[...q('#fi-currencies').querySelectorAll('input:checked')].map(e=>e.value).join(', ');}};
cards();refreshFlow();
})();
